    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg:
                if not seen[r][c]:
                    st=[(r,c)]; seen[r][c]=True; cells=[]
                    while st:
                        a,b=st.pop(); cells.append((a,b,I[a][b]))
                        for di in(-1,0,1):
                            for dj in(-1,0,1):
                                x,y=a+di,b+dj
                                if 0<=x<H and 0<=y<W and I[x][y]==I[a][b] and not seen[x][y]:
                                    seen[x][y]=True; st.append((x,y))
