            # must cover all template cells
            if okk and all(True for ddr,dcc,_ in [(q[0]-cell[0],q[1]-cell[1],qv) for q,qv in tmpl[tidx]['cells']]):
                return ((s[0]+dr,s[1]+dc),dr,dc,tidx)
